#!/usr/bin/env node

// Simple wrapper to set custom CA trust if available and run the real launcher
const { spawn } = require("child_process");
const path = require("path");
const fs = require("fs");

const __dirnameResolved = __dirname;

const env = { ...process.env };
const caPath = path.resolve(__dirnameResolved, "ca.pem");
if (fs.existsSync(caPath)) {
  env.NODE_EXTRA_CA_CERTS = caPath;
}

const startScript = path.resolve(__dirnameResolved, "_start.js");
const child = spawn(process.execPath, [startScript, ...process.argv.slice(2)], {
  env,
  stdio: "inherit",
});

child.on("close", (code) => process.exit(code));
child.on("error", (err) => {
  console.error("Failed to start Codex launcher:", err);
  process.exit(1);
});
